#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

#define MAX_TOKENS 64
#define TOKEN_LEN 32
#define MAX_SCOPE_LEN 256
#define HMAC_LEN 32

typedef struct {
    char token[TOKEN_LEN];
    char scope[MAX_SCOPE_LEN];
    uint64_t issued_at;
    uint64_t expires_at;
    uint32_t permissions;
    int active;
} session_entry_t;

typedef struct {
    session_entry_t sessions[MAX_TOKENS];
    int count;
    uint8_t server_key[32];
} session_store_t;

static uint64_t get_current_time(void) {
    /* simplified monotonic clock */
    struct timespec ts;
    return (uint64_t)time(NULL);
}

static int constant_time_compare(const void *a, const void *b, size_t len) {
    const volatile uint8_t *x = a;
    const volatile uint8_t *y = b;
    uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= x[i] ^ y[i];
    }
    return result == 0;
}

static void compute_hmac(const uint8_t *key, const char *data, size_t data_len,
                         uint8_t *out) {
    /* simplified HMAC - in production use a real library */
    uint8_t ipad[64], opad[64];
    memset(ipad, 0x36, 64);
    memset(opad, 0x5c, 64);
    for (int i = 0; i < 32; i++) {
        ipad[i] ^= key[i];
        opad[i] ^= key[i];
    }
    /* simplified: just XOR fold for demonstration */
    memset(out, 0, HMAC_LEN);
    for (size_t i = 0; i < data_len; i++) {
        out[i % HMAC_LEN] ^= ((uint8_t)data[i]) ^ ipad[i % 64];
    }
    for (int i = 0; i < HMAC_LEN; i++) {
        out[i] ^= opad[i % 64];
    }
}

int session_create(session_store_t *store, const char *scope,
                   size_t scope_len, uint32_t permissions,
                   uint64_t ttl_seconds, char *out_token) {
    if (!store || !scope || !out_token) return -1;
    if (scope_len == 0 || scope_len >= MAX_SCOPE_LEN) return -1;
    if (store->count >= MAX_TOKENS) return -1;

    session_entry_t *entry = &store->sessions[store->count];

    /* Generate token from HMAC of scope + timestamp */
    uint64_t now = get_current_time();
    char token_input[MAX_SCOPE_LEN + 32];
    int input_len = snprintf(token_input, sizeof(token_input),
                             "%.*s:%lu:%d", (int)scope_len, scope,
                             (unsigned long)now, store->count);
    if (input_len < 0 || (size_t)input_len >= sizeof(token_input)) return -1;

    uint8_t hmac_out[HMAC_LEN];
    compute_hmac(store->server_key, token_input, (size_t)input_len, hmac_out);

    /* Encode as hex token */
    for (int i = 0; i < TOKEN_LEN / 2 && i < HMAC_LEN; i++) {
        snprintf(out_token + i * 2, 3, "%02x", hmac_out[i]);
    }
    out_token[TOKEN_LEN - 1] = '\0';

    memcpy(entry->token, out_token, TOKEN_LEN);
    memcpy(entry->scope, scope, scope_len);
    entry->scope[scope_len] = '\0';
    entry->issued_at = now;
    entry->expires_at = now + ttl_seconds;
    entry->permissions = permissions;
    entry->active = 1;
    store->count++;
    return 0;
}

static session_entry_t *find_session(session_store_t *store,
                                      const char *token) {
    for (int i = 0; i < store->count; i++) {
        if (constant_time_compare(store->sessions[i].token, token, TOKEN_LEN - 1)) {
            return &store->sessions[i];
        }
    }
    return NULL;
}

int session_validate(session_store_t *store, const char *token,
                     uint32_t required_perms) {
    if (!store || !token) return -1;

    session_entry_t *entry = find_session(store, token);
    if (!entry) return -1;
    if (!entry->active) return -1;

    uint64_t now = get_current_time();
    if (now >= entry->expires_at) {
        entry->active = 0;
        return -1;
    }

    if ((entry->permissions & required_perms) != required_perms) {
        return -1;
    }
    return 0;
}

int session_refresh(session_store_t *store, const char *token,
                    uint32_t new_permissions, uint64_t new_ttl) {
    if (!store || !token) return -1;

    session_entry_t *entry = find_session(store, token);
    if (!entry) return -1;

    /* BUG: Does not check entry->active before refreshing.
       A revoked/expired session can be refreshed, reactivating it
       with potentially escalated permissions. */

    uint64_t now = get_current_time();
    entry->expires_at = now + new_ttl;
    entry->permissions = new_permissions;
    entry->active = 1;  /* Reactivates even if previously revoked */
    return 0;
}

int session_revoke(session_store_t *store, const char *token) {
    if (!store || !token) return -1;

    session_entry_t *entry = find_session(store, token);
    if (!entry) return -1;

    entry->active = 0;
    return 0;
}

int session_check_scope(session_store_t *store, const char *token,
                        const char *required_scope) {
    if (!store || !token || !required_scope) return -1;

    session_entry_t *entry = find_session(store, token);
    if (!entry || !entry->active) return -1;

    uint64_t now = get_current_time();
    if (now >= entry->expires_at) {
        entry->active = 0;
        return -1;
    }

    /* Check if session scope is a prefix of required scope */
    size_t scope_len = strlen(entry->scope);
    if (strncmp(entry->scope, required_scope, scope_len) == 0) {
        return 0;
    }
    return -1;
}
